package com.agacostays.payroll.mapper; import com.agacostays.payroll.entity.SalaryStructure; import com.agacostays.payroll.dto.response.SalaryStructureResponse; import org.springframework.stereotype.Component; @Component public class SalaryStructureMapper{public SalaryStructureResponse toResponse(SalaryStructure x){return new SalaryStructureResponse(x.getSalaryStructureId(),x.getRoleId(),x.getRoleName(),x.getBasicSalary(),x.getHra(),x.getAllowances(),x.getDeductions(),x.getMonthlyGrossSalary(),x.getMonthlyNetSalary(),x.getCurrency(),x.getEffectiveFrom(),x.getStatus().name(),x.getCreatedBy(),x.getCreatedAt(),x.getUpdatedAt());}}